<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Validador | AcquaVale</title><link rel="stylesheet" href="assets/css/app.css"></head><body class="validator"><div class="validator-card"><img src="https://www.acquavale.com.br/acquavale-logo.png" alt="AcquaVale" style="height:76px;display:block;margin:auto"><h1 style="text-align:center;color:var(--navy)">Validador de ingresso</h1><p style="text-align:center;color:var(--muted)">Tela auxiliar para testes. A catraca/face scanner usará a mesma API autenticada.</p><div class="form-group"><label>API key</label><input type="password" id="key" placeholder="Bearer token"></div><div class="form-group" style="margin-top:14px"><label>Código do ingresso</label><input id="ticket" class="ticket-code" autofocus placeholder="AQV-..."></div><div class="form-group" style="margin-top:14px"><label>Catraca</label><input id="gate" value="CATRACA-TESTE"></div><button class="btn btn-primary" id="validate" style="width:100%;margin-top:18px">Validar acesso</button><div class="validator-result" id="result">Aguardando leitura.</div></div><script>
const key=document.getElementById('key'),ticket=document.getElementById('ticket'),gate=document.getElementById('gate'),result=document.getElementById('result');key.value=localStorage.getItem('aqv_api_key')||'';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
async function validate(){localStorage.setItem('aqv_api_key',key.value);result.className='validator-result';result.innerHTML='Validando...';try{const r=await fetch('api.php?action=ticket-validate',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+key.value},body:JSON.stringify({ticket_code:ticket.value,gate_code:gate.value,idempotency_key:crypto.randomUUID()})});const d=await r.json();if(d.valid){result.className='validator-result notice success';result.innerHTML='<strong>ACESSO LIBERADO</strong><br>'+esc(d.ticket?.visitor_name||'Validação idempotente')+'<br>'+esc(d.ticket?.product||'')+'<br>'+esc(d.ticket?.valid_from||'')+' '+esc(d.ticket?.valid_to||'')}else{result.className='validator-result notice error';result.innerHTML='<strong>ACESSO NEGADO</strong><br>Motivo: '+esc(d.reason||d.error||'erro')}}catch(e){result.className='validator-result notice error';result.textContent='Falha de comunicação com a API.'}ticket.select()}
document.getElementById('validate').onclick=validate;ticket.addEventListener('keydown',e=>{if(e.key==='Enter')validate()});
</script></body></html>